for(const it of input){const r=it.json;const email=String(r.email||'').trim().toLowerCase();const domain=email.split('@')[1]||'';const reasons=[];const validEmail=emailRe.test(email);const mxStatus=!validEmail?'not_checked_invalid_email':!dns?'unknown_dns_module_unavailable':(mxByDomain[domain]||'unknown_dns_result');const bounceStatus=hardBounced.has(email)?'hard_bounce':'no_known_hard_bounce';
