const fs = require('fs');
const DATA = 'YOUR_PATH/data/files';
const FILE = DATA + '/suppression.csv';
const items = $input.all();
const rows = [];
const seen = new Set();
function collect(value, out, depth = 0) {
  if (depth > 8 || value == null) return;
  if (typeof value === 'string') { out.push(value); return; }
  if (Array.isArray(value)) { for (const v of value) collect(v, out, depth + 1); return; }
  if (typeof value === 'object') for (const [key, v] of Object.entries(value)) {
    if (!/attachments|binary/i.test(key)) collect(v, out, depth + 1);
  }
}
function addEmails(text, set) {
  const re = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig;
  let m;
  while ((m = re.exec(text)) !== null) set.add(m[0].toLowerCase());
}
function csv(value) { return '"' + String(value).replace(/"/g, '""') + '"'; }

for (const item of items) {
  const parts = [];
  collect(item.json, parts);
  const message = parts.join('\n');
  const hardFailure = /(?:status\s*[:=]\s*5\.[0-9]\.[0-9]|\b5\.[0-9]\.[0-9]\b|diagnostic-code[^\r\n]*\b5[0-9]{2}\b|smtp[^\r\n]*\b5[0-9]{2}\b)/i.test(message);
  const failureNotice = /delivery status notification|undeliver|mailer-daemon|mail delivery subsystem|permanent fatal|delivery failed|recipient address rejected/i.test(message);
  if (!hardFailure || !failureNotice) continue;
  const recipients = new Set();
  const lines = message.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    if (/^(?:final-recipient|original-recipient|x-failed-recipients|failed recipient|recipient address)\s*[:=]/i.test(lines[i])) {
      addEmails(lines[i], recipients);
    }
  }
  const marker = /following addresses had permanent fatal errors:?/i.exec(message);
  if (marker) {
    const block = message.slice(marker.index + marker[0].length).split(/\n\s*\n|-----|\n(?:please|see|the mail system)/i, 1)[0].slice(0, 1200);
    addEmails(block, recipients);
  }
  for (const email of recipients) {
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || seen.has(email)) continue;
    seen.add(email);
    rows.push({ email, reason: 'hard_bounce' });
  }
}
if (rows.length) {
  if (!fs.existsSync(DATA)) fs.mkdirSync(DATA, { recursive: true });
  const current = fs.existsSync(FILE) ? fs.readFileSync(FILE, 'utf8') : 'email,reason,added_at\n';
  const known = new Set(current.split(/\r?\n/).slice(1).map(line => (line.split(',')[0] || '').replace(/^\"|\"$/g, '').trim().toLowerCase()).filter(Boolean));
  const now = new Date().toISOString();
  const additions = rows.filter(row => !known.has(row.email)).map(row => [row.email, row.reason, now].join(',')).join('\n');
  if (additions) fs.appendFileSync(FILE, (current && !current.endsWith('\n') ? '\n' : '') + additions + '\n', 'utf8');
}
return rows.map(row => ({ json: { email: row.email, status: 'hard_bounce_added_to_suppression' } }));
